     BOOST_CHECK_EQUAL(out[0], 0x04 | (script[65] & 0x01)); // least significant bit (lsb) of last char of pubkey is mapped into out[0]
 }
 
+// ScriptCompression must encode the script in serialized_size bytes and decode it back unchanged
+static void CheckScriptCompressionRoundTrip(const CScript& script, size_t serialized_size)
+{
+    DataStream s = DataStream{} << Using<ScriptCompression>(script);
+    BOOST_CHECK_EQUAL(s.size(), serialized_size);
+    CScript restored;
+    s >> Using<ScriptCompression>(restored);
+    BOOST_CHECK(restored == script);
+}
+
 BOOST_AUTO_TEST_CASE(compress_p2pk_scripts_not_on_curve)
